import React, { useState } from 'react';
import './App.css';

function App() {
    const [selectedFile, setSelectedFile] = useState(null);
    const [preview, setPreview] = useState(null);
    const [processing, setProcessing] = useState(false);
    const [result, setResult] = useState(null);
    const [svgPreview, setSvgPreview] = useState(null);

    // Settings
    const [resolution, setResolution] = useState(512);
    const [contours, setContours] = useState(2);
    const [hatch, setHatch] = useState(16);

    const handleFileSelect = (e) => {
        const file = e.target.files[0];
        if (file) {
            setSelectedFile(file);

            // Create preview
            const reader = new FileReader();
            reader.onload = (e) => setPreview(e.target.result);
            reader.readAsDataURL(file);

            // Reset results
            setResult(null);
            setSvgPreview(null);
        }
    };

    const handleUpload = async () => {
        if (!selectedFile) return;

        setProcessing(true);
        setResult(null);
        setSvgPreview(null);

        const formData = new FormData();
        formData.append('file', selectedFile);
        formData.append('resolution', resolution);
        formData.append('contours', contours);
        formData.append('hatch', hatch);

        try {
            const response = await fetch('/api/upload', {
                method: 'POST',
                body: formData
            });

            const data = await response.json();

            if (data.error) {
                alert('Error: ' + data.error);
            } else {
                setResult(data);
                setSvgPreview(data.svg);
            }
        } catch (error) {
            alert('Upload failed: ' + error.message);
        } finally {
            setProcessing(false);
        }
    };

    const handleDownloadJSON = async () => {
        try {
            const response = await fetch('/api/download-json');
            const data = await response.json();

            if (data.error) {
                alert('Error: ' + data.error);
                return;
            }

            // Download as file
            const blob = new Blob([data.json], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'plotter-data.json';
            a.click();
            URL.revokeObjectURL(url);
        } catch (error) {
            alert('Download failed: ' + error.message);
        }
    };

    return (
        <div className="App">
            <header>
                <h1>Pen Plotter Control</h1>
            </header>

            <div className="container">
                {/* Upload Section */}
                <div className="card">
                    <h2>1. Upload Image</h2>

                    <div className="file-upload-wrapper">
                        <input
                            type="file"
                            accept="image/*"
                            onChange={handleFileSelect}
                            className="file-input"
                            id="file-upload"
                        />
                        <label htmlFor="file-upload" className="file-label">
                            {selectedFile ? selectedFile.name : 'Choose an image...'}
                        </label>
                    </div>

                    {preview && (
                        <div className="preview">
                            <img src={preview} alt="Preview" />
                        </div>
                    )}
                </div>

                {/* Settings Section */}
                <div className="card">
                    <h2>2. Processing Settings</h2>

                    <div className="settings">
                        <label>
                            <span className="label-text">Resolution: {resolution}px</span>
                            <input
                                type="range"
                                min="256"
                                max="1024"
                                step="128"
                                value={resolution}
                                onChange={(e) => setResolution(parseInt(e.target.value))}
                            />
                            <span className="hint">Higher = more detail, slower processing</span>
                        </label>

                        <label>
                            <span className="label-text">Contour Detail: {contours}</span>
                            <input
                                type="range"
                                min="0"
                                max="10"
                                value={contours}
                                onChange={(e) => setContours(parseInt(e.target.value))}
                            />
                            <span className="hint">0 = none, 10 = maximum detail</span>
                        </label>

                        <label>
                            <span className="label-text">Hatching: {hatch > 0 ? hatch : 'Off'}</span>
                            <input
                                type="range"
                                min="0"
                                max="32"
                                step="4"
                                value={hatch}
                                onChange={(e) => setHatch(parseInt(e.target.value))}
                            />
                            <span className="hint">0 = off, lower number = denser shading</span>
                        </label>
                    </div>

                    <button
                        onClick={handleUpload}
                        disabled={!selectedFile || processing}
                        className="btn btn-primary"
                    >
                        {processing ? 'Processing...' : 'Process Image'}
                    </button>
                </div>

                {/* Results Section */}
                {result && (
                    <div className="card">
                        <h2>3. Preview & Download</h2>

                        <div className="stats">
                            <div className="stat">
                                <span className="stat-label">Lines</span>
                                <span className="stat-value">{result.lines_count}</span>
                            </div>
                            <div className="stat">
                                <span className="stat-label">Segments</span>
                                <span className="stat-value">{result.segments_count}</span>
                            </div>
                            <div className="stat">
                                <span className="stat-label">Est. Time</span>
                                <span className="stat-value">{result.estimated_time_minutes} min</span>
                            </div>
                        </div>

                        {svgPreview && (
                            <div className="svg-preview-container">
                                <div
                                    className="svg-preview"
                                    dangerouslySetInnerHTML={{ __html: svgPreview }}
                                />
                            </div>
                        )}

                        <div className="download-section">
                            <button
                                onClick={handleDownloadJSON}
                                className="btn btn-download"
                            >
                                Download JSON
                            </button>
                        </div>

                        <div className="instructions">
                            <h3>To view with Turtle Graphics:</h3>
                            <ol>
                                <li>Download the JSON file above</li>
                                <li>Open Terminal and navigate to: <code>backend/</code></li>
                                <li>Activate virtual environment: <code>source venv/bin/activate</code></li>
                                <li>Run: <code>python turtle_viewer.py ~/Downloads/plotter-data.json</code></li>
                            </ol>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

export default App;
